import { Fragment, ReactNode, useState } from "react";
import { useTranslation } from "react-i18next";
import styles from "./media-gallery-block.module.less";
import { Carousel } from "@/core/components/primitives/carousel/carousel";
import { Lightbox, LightboxItem } from "@/core/components/primitives/light-box/light-box";
import { Icon } from "@/core/components/primitives/icon/icon";
import { multipleClassNames, EventAggregator, isNonEmptyArray } from "@/core/helpers";

export type MediaGalleryItem = LightboxItem & {
  /** Contentful asset url, used for the thumbnail and for image items in the lightbox */
  url: string;
  imageWidth?: number;
  imageHeight?: number;
  alt?: string;
};

export type RenderItemHelpers = {
  /** Opens the lightbox at this item (and tracks the click) */
  openLightbox: () => void;
  /** The play icon overlay to render on top of youtube thumbnails (undefined for image items) */
  playIcon: ReactNode;
  /**
   * Styling for the `<button>` that wraps a site-rendered thumbnail.
   * The thumbnail needs to be a button to be reachable with the keyboard and to get focus back when the lightbox closes.
   */
  buttonClassName: string;
  /** Thumbnail styling for sites that render items with a background-image component (inside the button) */
  imageClassName: string;
  /** Describes what the thumbnail opens, to set on the clickable element */
  ariaLabel: string;
};

export type Props = {
  contentfulId: string;
  title?: string;
  items: Array<MediaGalleryItem>;
  /** Heading element used for the title */
  titleTag?: "h2" | "h3" | "h4" | "h5";
  /** Extra classes on the outer <section> (e.g. the sites' global block classes and theming hooks) */
  className?: string;
  /** Extra classes on the title element (e.g. a site's global "h2" class) */
  classNameTitle?: string;
  /** Extra classes on the content wrapper inside the section (e.g. a site's global max-width class) */
  classNameContent?: string;
  /** Set by background-wrapper-block so the block can drop its own background. Rendered as a data attribute for the sites' theming to target. */
  inBackgroundWrapper?: boolean;
  /**
   * Site-specific thumbnail renderer, for sites that still render thumbnails with their own
   * image component. Wrap the thumbnail in a <button> with `helpers.buttonClassName`.
   * When omitted, a <button> with a <picture> is rendered.
   */
  renderItem?: (item: MediaGalleryItem, index: number, helpers: RenderItemHelpers) => ReactNode;
};

const MediaGalleryBlock = ({
  contentfulId,
  title,
  items,
  titleTag: TitleTag = "h2",
  className,
  classNameTitle,
  classNameContent,
  inBackgroundWrapper,
  renderItem,
}: Props) => {
  const [lightboxOpenedIndex, setLightboxOpenedIndex] = useState(-1);

  const { t } = useTranslation();

  const showLightbox = (index: number) => {
    setLightboxOpenedIndex(index);
    EventAggregator.publish("trackEvent", {
      category: "Media Gallery",
      action: "Opened",
      label: "Image " + (index + 1),
    });
  };

  // Nothing to show without media, so hide the whole block rather than render an empty carousel
  if (!isNonEmptyArray(items)) {
    return null;
  }

  const isSingleItem = items.length === 1;

  return (
    <section
      className={multipleClassNames(styles.mediaGallery, className)}
      data-contentful-id={contentfulId}
      data-in-background-wrapper={inBackgroundWrapper}
    >
      <div className={classNameContent}>
        {title && <TitleTag className={multipleClassNames(styles.title, classNameTitle)}>{title}</TitleTag>}
        <div className={styles.innerWrapper}>
          <Carousel
            classNameListItem={multipleClassNames(styles.carouselListItem, isSingleItem && styles.singleItem)}
            classNamePrevBtn={styles.carouselPrevBtn}
            classNameNextBtn={styles.carouselNextBtn}
            navDots={true}
          >
            {items.map((item, index) => {
              const isVideo = item.type === "youtube";
              const helpers: RenderItemHelpers = {
                openLightbox: () => showLightbox(index),
                playIcon: isVideo ? <Icon name="play" className={styles.playIcon} /> : undefined,
                buttonClassName: styles.listItemBkgImageButton,
                imageClassName: styles.listItemBkgImage,
                ariaLabel: t(isVideo ? "mediaGalleryPlayVideoAriaLabel" : "mediaGalleryOpenImageAriaLabel", {
                  number: index + 1,
                  total: items.length,
                }),
              };

              return (
                <Fragment key={index}>
                  {renderItem ? renderItem(item, index, helpers) : <DefaultItem item={item} helpers={helpers} />}
                </Fragment>
              );
            })}
          </Carousel>
        </div>
      </div>
      <Lightbox
        items={items}
        isOpen={lightboxOpenedIndex !== -1}
        onClose={() => setLightboxOpenedIndex(-1)}
        initialIndex={lightboxOpenedIndex}
      />
    </section>
  );
};

const DefaultItem = ({ item, helpers }: { item: MediaGalleryItem; helpers: RenderItemHelpers }) => {
  return (
    <button className={styles.listItemButton} onClick={helpers.openLightbox} aria-label={helpers.ariaLabel}>
      <picture className={styles.picture}>
        <source srcSet={`${item.url}?w=800&q=70&fm=webp,`} type="image/webp" />
        <source srcSet={`${item.url}?w=800&q=70`} />
        <img
          className={styles.image}
          src={`${item.url}?w=500&q=70`}
          alt={item.alt ? item.alt : ""}
          loading="lazy"
          width={item.imageWidth ? item.imageWidth : undefined}
          height={item.imageHeight ? item.imageHeight : undefined}
        />
      </picture>
      {helpers.playIcon}
    </button>
  );
};

export default MediaGalleryBlock;
